# import stl_path
from builtins import str
import os
import traceback
import imp

# from scapy.contrib.gtp import *
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger

logger = BackgroundLogger.Instance()

try:
    from trex.stl.api import *
except ImportError:
    logger.warn(
        "Trex libraries are not available!!!Trex keywords will not work !!")


def load_namespace_py(python_file, direction=0, port_id=0, **kwargs):
    """ Load from Python profile """

    # check filename
    if not os.path.isfile(python_file):
        raise TRexError("File '{0}' does not exist".format(python_file))

    basedir = os.path.dirname(python_file)
    sys.path.insert(0, basedir)
    dont_write_bytecode = sys.dont_write_bytecode

    try:
        file = os.path.basename(python_file).split('.')[0]
        sys.dont_write_bytecode = True
        module = __import__(file, globals(), locals(), [], 0)
        imp.reload(module)  # reload the update

        # t = STLProfile.get_module_tunables(module)
        # for arg in kwargs:
        #    if arg not in t:
        #        raise TRexError("Profile {0} does not support tunable '{1}' - supported tunables are: '{2}'".format(
        #        python_file, arg, t))

        streams = module.register().get_ns(direction=direction,
                                           port_id=port_id,
                                           **kwargs)

        print("The Ns objects are {}".format(streams))
        return streams

    except Exception as e:
        a, b, tb = sys.exc_info()
        x = ''.join(traceback.format_list(traceback.extract_tb(tb)
                                          [1:])) + a.__name__ + ": " + str(b) + "\n"

        summary = "\nPython Traceback follows:\n\n" + x
        raise TRexError(summary)

    finally:
        sys.dont_write_bytecode = dont_write_bytecode
        sys.path.remove(basedir)
